import '@kerfjs/ui/layout.css';
import './list-workspace.css';

import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { delegate, signal } from 'kerfjs';

type LoadState = 'loading' | 'ready' | 'refreshing' | 'error';
type Task = { id: string; title: string; meta: string };

export function createListWorkspace(root: HTMLElement, load: () => Promise<Task[]>) {
  const state = signal<LoadState>('loading');
  const items = signal<Task[]>([]);

  const fetchTasks = async (background = false) => {
    state.value = background && items.value.length ? 'refreshing' : 'loading';
    try {
      items.value = await load();
      state.value = 'ready';
    } catch {
      state.value = 'error';
    }
  };

  const renderRows = () => <ul class="task-list" aria-label="Release tasks">{items.value.map((item) => <li data-key={item.id}><strong>{item.title}</strong><span>{item.meta}</span></li>)}</ul>;
  const renderBody = () => {
    if (state.value === 'loading' && items.value.length === 0) return <EmptyState title="Loading release tasks" detail="The current workspace will appear when data is ready." busy />;
    if (state.value === 'ready' && items.value.length === 0) return <EmptyState title="No release tasks" detail="Create the first task for this milestone." action={<button class="workspace-button" data-primary="true" type="button" data-action="create-task">Create task</button>} />;
    return <div class="kui-section-stack">
      {state.value === 'refreshing' && <StateBanner title="Showing saved results" detail="Refreshing in the background; the current tasks remain available." tone="warning" action={<LoadingSpinner label="Refreshing release tasks" />} />}
      {state.value === 'error' && <StateBanner title="Release tasks could not be refreshed" detail="Saved results remain below. Try again when the connection recovers." tone="danger" urgency="alert" action={<button class="workspace-button" type="button" data-action="retry">Retry</button>} />}
      {renderRows()}
    </div>;
  };

  const render = () => <section class="list-workspace kui-layout" aria-busy={String(state.value === 'loading' || state.value === 'refreshing')}><PageHeader title="Release tasks" action={<button class="workspace-button" type="button" data-action="refresh">Refresh</button>} /><div class="list-workspace__scroll kui-scroll-owner kui-pane-body">{renderBody()}</div></section>;
  const dispose = delegate(root, 'click', '[data-action]', (_event, element) => { if (element.dataset.action === 'refresh' || element.dataset.action === 'retry') void fetchTasks(items.value.length > 0); });
  void fetchTasks();
  return { render, refresh: () => fetchTasks(true), dispose };
}

