.list-workspace { display: grid; min-block-size: 0; block-size: 100%; grid-template-rows: auto minmax(0, 1fr); }
.list-workspace__scroll { min-block-size: 0; }
.task-list { display: grid; margin: 0; padding: 0; list-style: none; }
.task-list li { display: grid; gap: var(--kui-layout-metadata-gap); padding-block: var(--kui-space-s); border-block-end: 1px solid var(--kui-color-border-quiet); }
.task-list li span { color: var(--kui-color-text-quiet); }
.workspace-button { min-block-size: 2rem; padding: var(--kui-space-xs) var(--kui-space-s); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); color: var(--kui-color-text); background: var(--kui-color-surface); }
.workspace-button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
